                                     </div>
                                     <div className="md:col-span-2 flex items-end">
                                         <button type="submit" className="bg-orange-600 hover:bg-orange-500 text-white font-black w-full py-4 rounded-2xl shadow-xl transition-all flex items-center justify-center gap-2">
                                             <Zap className="w-5 h-5"/> INITIALIZE PROMO PROTOCOL
                                         </button>
                                     </div>
                                 </form>
                             )}

                             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                 {promos.map(p => (
                                     <div key={p.id} className={`bg-zinc-950 p-6 rounded-3xl border-2 transition-all relative overflow-hidden group ${p.active ? 'border-orange-500/20' : 'border-zinc-800 opacity-50'}`}>
                                         <div className="flex justify-between items-start mb-6">
                                             <div className="flex items-center gap-2">
                                                <span className="text-2xl font-black tracking-tighter uppercase text-white">{p.code}</span>
                                                <button onClick={() => togglePromoStatus(p)} className={`p-1.5 rounded-lg ${p.active ? 'bg-green-600' : 'bg-zinc-800'} text-white`}>
                                                    {p.active ? <Check className="w-3 h-3"/> : <Ban className="w-3 h-3"/>}
                                                </button>
                                             </div>
                                             <button onClick={() => deletePromo(p.id!)} className="p-2 text-zinc-600 hover:text-red-500"><Trash2 className="w-4 h-4"/></button>
                                         </div>
                                         <div className="flex items-baseline gap-2 mb-4">
                                             <span className="text-4xl font-black text-orange-500">{p.discountType === 'PERCENT' ? `${p.discountValue}%` : `₹${p.discountValue}`}</span>
                                             <span className="text-[10px] font-bold text-zinc-500 uppercase">OFF</span>
                                         </div>
                                         <div className="space-y-2 border-t border-white/5 pt-4">
                                            <div className="flex justify-between text-[10px] font-bold uppercase">
                                                <span className="text-zinc-500">Claims</span>
                                                <span className="text-white">{p.currentClaims} / {p.maxClaims}</span>
                                            </div>
                                            <div className="w-full bg-zinc-900 h-1.5 rounded-full overflow-hidden">
                                                <div className="bg-orange-500 h-full" style={{ width: `${(p.currentClaims / p.maxClaims) * 100}%` }}></div>
                                            </div>
                                         </div>
                                     </div>
                                 ))}
                             </div>
                        </div>
                    </div>
                )}

                {activeTab === 'BROADCAST' && (
                    <div className="bg-zinc-900/50 p-10 rounded-[2.5rem] border border-white/5 shadow-2xl animate-fade-in">
                        <div className="flex items-center gap-4 mb-10">
                            <div className="bg-blue-600 p-3 rounded-2xl shadow-[0_0_20px_rgba(37,99,235,0.4)]">
                                <Layout className="w-6 h-6 text-white" />
                            </div>
                            <div>
                                <h2 className="text-3xl font-black uppercase tracking-tighter">Broadcast Packages</h2>
                                <p className="text-zinc-500 text-[10px] font-bold uppercase tracking-widest mt-1">Manage scoreboard registry visibility</p>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                            {THEMES_LIST.map(theme => {
                                const isHidden = hiddenThemes.includes(theme.id);
                                return (
                                    <div key={theme.id} className={`bg-zinc-950 p-6 rounded-3xl border-2 transition-all relative overflow-hidden group ${isHidden ? 'border-zinc-800 opacity-50' : 'border-blue-500/30 hover:border-blue-500'}`}>
                                        <div className="flex justify-between items-start mb-4">
                                            <div className="bg-zinc-900 px-3 py-1 rounded-full text-[8px] font-black text-blue-400 uppercase tracking-[0.2em] border border-white/5">
                                                {theme.year}
                                            </div>
                                            <button 
                                                onClick={() => toggleThemeVisibility(theme.id)}
                                                disabled={updatingThemes}
                                                className={`p-2 rounded-xl transition-all ${isHidden ? 'bg-zinc-800 text-zinc-500 hover:text-white' : 'bg-blue-600 text-white shadow-lg'}`}
                                            >
                                                {isHidden ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                                            </button>
                                        </div>
                                        <h3 className="text-sm font-black uppercase tracking-tight text-white mb-2">{theme.label}</h3>
                                        <p className="text-[9px] text-zinc-500 font-bold uppercase tracking-widest">{isHidden ? 'Currently Hidden' : 'Active Registry'}</p>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                )}

                {activeTab === 'GRAPHICS' && (
                    <div className="bg-zinc-900/50 p-10 rounded-[2.5rem] border border-white/5 shadow-2xl animate-fade-in">
                        <div className="flex items-center gap-4 mb-10">
                            <div className="bg-emerald-600 p-3 rounded-2xl shadow-[0_0_20px_rgba(16,185,129,0.4)]">
                                <ImageIcon className="w-6 h-6 text-white" />
                            </div>
                            <div>
                                <h2 className="text-3xl font-black uppercase tracking-tighter">Global Scoreboard Backgrounds</h2>
                                <p className="text-zinc-500 text-[10px] font-bold uppercase tracking-widest mt-1">Upload backgrounds available for all scoring matches</p>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
                            <div className="bg-black/40 p-8 rounded-3xl border border-white/5 space-y-6">
                                <div>
                                    <label className="block text-[10px] font-black text-zinc-500 uppercase tracking-widest mb-2">Background Name</label>
                                    <input 
                                        type="text" 
                                        className="w-full bg-zinc-900 border border-zinc-800 rounded-2xl py-4 px-6 text-xs font-black uppercase tracking-widest outline-none focus:border-emerald-500 transition-all" 
                                        placeholder="E.G. FINALS BACKGROUND"
                                        value={newAssetName}
                                        onChange={e => setNewAssetName(e.target.value)}
                                    />
                                </div>
                                <div 
                                    onClick={() => assetFileRef.current?.click()}
                                    className="aspect-video bg-zinc-900 border-2 border-dashed border-zinc-800 rounded-3xl flex flex-col items-center justify-center p-4 cursor-pointer hover:bg-zinc-800/50 transition-all group relative overflow-hidden"
                                >
                                    {assetPreview ? (
                                        <img src={assetPreview} className="max-h-full max-w-full object-contain relative z-10" />
                                    ) : (
                                        <>
                                            <Upload className="w-10 h-10 text-zinc-700 group-hover:text-emerald-500 transition-colors mb-2" />
                                            <p className="text-[10px] font-black text-zinc-600 uppercase tracking-widest">Select Image</p>
                                        </>
                                    )}
                                    <input ref={assetFileRef} type="file" className="hidden" accept="image/*" onChange={handleAssetFileChange} />
                                </div>
                                <button 
                                    onClick={handleUploadGlobalAsset}
                                    disabled={uploadingAsset || !assetPreview || !newAssetName}
                                    className="w-full bg-emerald-600 hover:bg-emerald-500 disabled:opacity-50 text-white font-black py-4 rounded-2xl flex items-center justify-center gap-3 transition-all active:scale-95 shadow-xl"
                                >
                                    {uploadingAsset ? <RefreshCw className="w-5 h-5 animate-spin" /> : <Plus className="w-5 h-5" />}
                                    UPLOAD GLOBAL BACKGROUND
                                </button>
                            </div>

                            <div className="lg:col-span-2 grid grid-cols-2 md:grid-cols-3 gap-6 overflow-y-auto max-h-[500px] pr-4 custom-scrollbar">
                                {globalAssets.map(asset => (
                                    <div key={asset.id} className="bg-zinc-950 rounded-3xl border border-zinc-800 overflow-hidden group relative">
                                        <div className="aspect-video bg-black flex items-center justify-center relative">
                                            <img src={asset.url} className="max-h-full transition-transform group-hover:scale-105" />
                                            <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-4">
                                                <button 
                                                    onClick={() => deleteGlobalAsset(asset.id)}
                                                    className="bg-red-600 text-white p-3 rounded-2xl shadow-xl hover:scale-110 active:scale-90 transition-all"
                                                >
                                                    <Trash2 className="w-5 h-5" />
                                                </button>
                                            </div>
                                        </div>
                                        <div className="p-4">
                                            <p className="font-black text-[10px] uppercase tracking-tighter truncate text-zinc-400">{asset.name}</p>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                )}
            </main>
        </div>
    );
};

export default SuperAdminDashboard;

import React, { useEffect, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { useAuction } from '../hooks/useAuction';
import { Plus, Search, Menu, AlertCircle, RefreshCw, Database, Trash2, Cast, Monitor, Activity, UserPlus, Link as LinkIcon, ShieldCheck, CreditCard, Scale, FileText, ChevronRight, CheckCircle, Info, Zap, Crown, Users, Gavel, Sparkles, Shield, Book, HelpCircle, UserPlus2, Layout, Youtube, MessageSquare, Star, Trophy, Tag, Check, ShieldAlert, LogOut, AlertTriangle, Clock } from 'lucide-react';
import { db } from '../firebase';
import { AuctionSetup, UserPlan, UserRole, PromoCode } from '../types';

const AdminDashboard: React.FC = () => {
  const { userProfile, logout } = useAuction();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [auctions, setAuctions] = useState<(AuctionSetup & { currentTeamCount?: number })[]>([]);
  const [dbPlans, setDbPlans] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'AUCTIONS' | 'PLANS' | 'LEGAL'>('AUCTIONS');
  const [isRazorpayLoaded, setIsRazorpayLoaded] = useState(false);
  const [selectedAuctionForUpgrade, setSelectedAuctionForUpgrade] = useState<string | null>(null);

  // Promo Code States
  const [promoInput, setPromoInput] = useState('');
  const [appliedPromo, setAppliedPromo] = useState<PromoCode | null>(null);
  const [promoError, setPromoError] = useState('');
  const [isValidatingPromo, setIsValidatingPromo] = useState(false);

  const isSuperAdmin = userProfile?.role === UserRole.SUPER_ADMIN;

  const COMMON_FEATURES = [
      { name: 'Online player registration', icon: <UserPlus2 className="w-4 h-4" /> },
      { name: 'Excel Data entry support', icon: <FileText className="w-4 h-4" /> },
      { name: 'Public Auction Page', icon: <Layout className="w-4 h-4" /> },
      { name: 'Auto points calculation', icon: <Zap className="w-4 h-4" /> },
      { name: 'WhatsApp Player Updates', icon: <MessageSquare className="w-4 h-4" /> },
      { name: 'LED/Projector Views', icon: <Monitor className="w-4 h-4" /> },
      { name: 'YouTube Overlays', icon: <Youtube className="w-4 h-4" /> },
  ];

  // Detect auto-upgrade query param
  useEffect(() => {
    const upgradeId = searchParams.get('upgrade');
    if (upgradeId) {
        setSelectedAuctionForUpgrade(upgradeId);
        setActiveTab('AUCTIONS');
    }
  }, [searchParams]);

  // Load Razorpay Script
  useEffect(() => {
    const script = document.createElement('script');
    script.src = 'https://checkout.razorpay.com/v1/checkout.js';
    script.async = true;
    script.onload = () => setIsRazorpayLoaded(true);
    document.body.appendChild(script);
    return () => { if (document.body.contains(script)) document.body.removeChild(script); };
  }, []);

  // Fetch Dynamic Plans or fallback to defaults matching the requested image (limited to 15 teams)
  useEffect(() => {
      const unsub = db.collection('subscriptionPlans').orderBy('price', 'asc').onSnapshot(snap => {
          if (snap.empty) {
              setDbPlans([
                  { id: 'plan_1', name: 'Plan 1 - Free', price: 0, teams: 2 },
                  { id: 'plan_2', name: 'Plan 2', price: 3000, teams: 4 },
                  { id: 'plan_3', name: 'Plan 3', price: 4000, teams: 6 },
                  { id: 'plan_4', name: 'Plan 4', price: 5000, teams: 10 },
                  { id: 'plan_5', name: 'Plan 5', price: 6000, teams: 15 },
              ]);
          } else {
              setDbPlans(snap.docs.map(d => ({ id: d.id, ...d.data() })).filter(p => p.teams <= 15));
          }
      });
      return () => unsub();
  }, []);

  const setupListener = () => {
        if (!userProfile?.uid) return () => {};
        setLoading(true);
        setError(null);
        try {
            const unsubscribe = db.collection('auctions')
                .where('createdBy', '==', userProfile.uid)
                .onSnapshot(async (snapshot) => {
                    const auctionsData = snapshot.docs.map(d => ({ id: d.id, ...d.data() } as AuctionSetup));

                    // Fetch team counts for each auction to validate plans
                    const auctionsWithCounts = await Promise.all(auctionsData.map(async (a) => {
                        const teamsSnap = await db.collection('auctions').doc(a.id).collection('teams').get();
                        return { ...a, currentTeamCount: teamsSnap.size };
                    }));

                    auctionsWithCounts.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
                    setAuctions(auctionsWithCounts);
                    setLoading(false);
                }, (error: any) => {
                    setLoading(false);
                    setError("Failed to load auctions: " + error.message);
                });
            return unsubscribe;
        } catch (e: any) {
            setError(e.message);
            setLoading(false);
            return () => {};
        }
  };

  useEffect(() => {
    let unsubscribe: any;
    if (userProfile?.uid) { unsubscribe = setupListener(); }
    return () => { if (unsubscribe) unsubscribe(); };
  }, [userProfile]);

  const handleValidatePromo = async () => {
      if (!promoInput) return;
      setIsValidatingPromo(true);
      setPromoError('');
      setAppliedPromo(null);
      try {
          const snap = await db.collection('promoCodes').where('code', '==', promoInput.toUpperCase()).get();
          if (snap.empty) throw new Error("Invalid Promo Code");
          const promo = { id: snap.docs[0].id, ...snap.docs[0].data() } as PromoCode;
          if (!promo.active) throw new Error("Promo Code Inactive");
          if (promo.expiryDate < Date.now()) throw new Error("Promo Code Expired");
          if (promo.currentClaims >= promo.maxClaims) throw new Error("Promo Claim Limit Reached");
          setAppliedPromo(promo);
      } catch (err: any) {
          setPromoError(err.message);
      } finally {
          setIsValidatingPromo(false);
      }
  };

  const calculateDiscountedPrice = (originalPrice: number) => {
      if (!appliedPromo) return originalPrice;
      if (appliedPromo.discountType === 'FLAT') return Math.max(0, originalPrice - appliedPromo.discountValue);
      return Math.max(0, Math.round(originalPrice * (1 - appliedPromo.discountValue / 100)));
  };

  const handleAuctionSubscription = (auctionId: string, plan: any) => {
      if (!isRazorpayLoaded) return alert("Payment system is loading...");
      if (plan.price === 0) return alert("This auction is already on the Free Plan.");

      const finalPrice = calculateDiscountedPrice(plan.price);

      // If price becomes zero due to promo, bypass Razorpay
      if (finalPrice === 0) {
          (async () => {
              await db.collection('auctions').doc(auctionId).update({
                  isPaid: true,
                  planId: plan.id,
                  totalTeams: plan.teams 
              });
              if (appliedPromo) {
                  await db.collection('promoCodes').doc(appliedPromo.id).update({
                      currentClaims: (appliedPromo.currentClaims || 0) + 1
                  });
              }
              alert("Protocol Authorized! Full Discount Applied.");
              setSelectedAuctionForUpgrade(null);
          })();
          return;
      }

      const options = {
          key: "rzp_test_pnZyMfa3h3mMXR",
          amount: finalPrice * 100,
          currency: "INR",
          name: "SM SPORTS",
          description: `Upgrade Auction: ${plan.name} ${appliedPromo ? '(Promo Applied)' : ''}`,
          handler: async (response: any) => {
              await db.collection('auctions').doc(auctionId).update({
                  isPaid: true,
                  planId: plan.id,
                  totalTeams: plan.teams 
              });
              if (appliedPromo) {
                  await db.collection('promoCodes').doc(appliedPromo.id).update({
                      currentClaims: (appliedPromo.currentClaims || 0) + 1
                  });
              }
              alert("Success! Your auction has been upgraded.");
              setSelectedAuctionForUpgrade(null);
          },
          prefill: { email: userProfile?.email },
          theme: { color: "#16a34a" }
      };
      const rzp = new (window as any).Razorpay(options);
      rzp.open();
  };

  const copyRegLink = (auctionId: string) => {
      const baseUrl = window.location.href.split('#')[0];
      const url = `${baseUrl}#/auction/${auctionId}/register`;
      navigator.clipboard.writeText(url);
      alert("✅ Registration link copied!");
  };

  const handleDeleteAuction = async (auctionId: string, title: string) => {
      if (window.confirm(`Delete auction "${title}"?`)) {
          try { await db.collection('auctions').doc(auctionId).delete(); } 
          catch (e: any) { alert("Delete failed: " + e.message); }
      }
  };

  const renderAuctions = () => (
      <div className="space-y-6 animate-fade-in">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
              <h2 className="text-2xl font-bold text-gray-800 tracking-tight">My Auctions ({auctions.length})</h2>
              <div className="flex gap-2">
                  <button onClick={() => navigate('/scoring')} className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-6 rounded-xl shadow shadow-blue-900/10 transition-all flex items-center text-xs"><Activity className="w-4 h-4 mr-2" /> SCORING</button>
                  <button onClick={() => navigate('/admin/new')} className="bg-green-600 hover:bg-green-700 text-white font-bold py-2 px-6 rounded-xl shadow shadow-green-900/10 transition-all flex items-center text-xs"><Plus className="w-4 h-4 mr-2" /> NEW AUCTION</button>
              </div>
          </div>

          {/* System Deletion Warnings */}
          <div className="space-y-2">
            {auctions.filter(a => a.autoDeleteAt).map(auction => {
                const diffDays = Math.ceil((auction.autoDeleteAt! - Date.now()) / (1000 * 60 * 60 * 24));
                if (diffDays <= 7) {
                    return (
                        <div key={`warn-${auction.id}`} className="bg-red-50 border-l-4 border-red-500 p-4 rounded-xl flex items-center justify-between gap-4 animate-pulse shadow-sm">
                            <div className="flex items-center gap-3">
                                <AlertTriangle className="text-red-500 w-5 h-5 shrink-0" />
                                <div>
                                    <p className="text-xs font-black text-red-800 uppercase">System Notice: Deletion Protocol Scheduled</p>
                                    <p className="text-[10px] text-red-600 font-bold uppercase">Auction <b className="text-red-800">"{auction.title}"</b> will be purged in {diffDays} days ({new Date(auction.autoDeleteAt!).toLocaleDateString()}).</p>
                                </div>
                            </div>
                            <button onClick={() => navigate(`/admin?upgrade=${auction.id}`)} className="bg-red-600 hover:bg-red-700 text-white text-[9px] font-black px-4 py-2 rounded-lg uppercase tracking-widest transition-all">Extend Retention</button>
                        </div>
                    );
                }
                return null;
            })}
          </div>

          <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
                {loading ? (
                    <div className="p-12 text-center text-gray-500 flex flex-col items-center">
                        <RefreshCw className="animate-spin h-8 w-8 text-green-600 mb-2"/>
                        Loading auctions...
                    </div>
                ) : (
                    <div className="divide-y divide-gray-100">
                        {auctions.length > 0 ? auctions.map((auction) => (
                            <div key={auction.id} id={`auction-${auction.id}`} className={`p-0 transition-colors group ${selectedAuctionForUpgrade === auction.id ? 'bg-blue-50/20' : 'hover:bg-gray-50/50'}`}>
                                <div className="p-6 flex flex-col md:flex-row justify-between md:items-center gap-4">
                                    <div className="flex-1 flex items-center gap-4">
                                        <div className={`w-12 h-12 rounded-xl flex items-center justify-center font-bold text-white shadow-lg ${auction.isPaid ? 'bg-gradient-to-br from-green-500 to-green-700' : 'bg-gradient-to-br from-gray-400 to-gray-500'}`}>
                                            {auction.isPaid ? <ShieldCheck className="w-6 h-6"/> : <Gavel className="w-6 h-6"/>}
                                        </div>
                                        <div>
                                            <h4 className="font-bold text-gray-800 text-lg">{auction.title}</h4>
                                            <div className="flex flex-wrap items-center gap-3 mt-1">
                                                <p className="text-xs text-gray-400 font-semibold">{auction.sport} • {auction.date}</p>
                                                <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full border ${auction.isPaid ? 'bg-green-50 border-green-200 text-green-600' : 'bg-gray-100 border-gray-200 text-gray-500'}`}>
                                                    {auction.isPaid ? 'Paid Version' : 'Free Version'}
                                                </span>
                                                {auction.autoDeleteAt && (
                                                    <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-orange-50 border border-orange-200 text-orange-600 flex items-center gap-1">
                                                        <Clock className="w-2.5 h-2.5"/> Wipe: {new Date(auction.autoDeleteAt).toLocaleDateString()}
                                                    </span>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                    <div className="flex flex-wrap items-center gap-2">
                                        {!auction.isPaid && userProfile?.role !== UserRole.SUPER_ADMIN && (
                                            <button 
                                                onClick={() => { setSelectedAuctionForUpgrade(selectedAuctionForUpgrade === auction.id ? null : auction.id!); setPromoInput(''); setAppliedPromo(null); setPromoError(''); }}
                                                className={`px-4 py-1.5 rounded-xl text-xs font-bold border transition-all flex items-center gap-2 ${selectedAuctionForUpgrade === auction.id ? 'bg-blue-600 text-white border-blue-600' : 'bg-blue-50 text-blue-600 border-blue-100 hover:bg-blue-100'}`}
                                            >
                                                <CreditCard className="w-3 h-3" /> Upgrade
                                            </button>
                                        )}
                                        <button onClick={() => copyRegLink(auction.id!)} className="text-emerald-600 hover:bg-emerald-50 px-3 py-1.5 rounded-xl text-xs font-bold border border-emerald-100 flex items-center transition-all"><LinkIcon className="w-3 h-3 mr-1" /> Reg Link</button>
                                        <button onClick={() => navigate(`/auction/${auction.id}`)} className="bg-white border border-gray-200 text-gray-700 px-3 py-1.5 rounded-xl text-xs font-bold hover:bg-gray-100 transition-all">Live Room</button>
                                        <button onClick={() => navigate(`/admin/auction/${auction.id}/manage`)} className="bg-white border border-gray-200 text-gray-700 px-3 py-1.5 rounded-xl text-xs font-bold hover:bg-gray-100 transition-all">Manage</button>
                                        <button onClick={() => handleDeleteAuction(auction.id!, auction.title)} className="text-red-400 hover:text-red-600 p-2 rounded transition-colors"><Trash2 className="w-4 h-4" /></button>
                                    </div>
                                </div>

                                {/* Inline Plan Selector - Restricted to 15 teams */}
                                {selectedAuctionForUpgrade === auction.id && (
                                    <div className="bg-blue-50/50 p-6 border-t border-blue-100 animate-slide-up">
                                        <div className="flex flex-col md:flex-row justify-between gap-6 mb-8">
                                            <div className="flex items-start gap-3">
