Yes, you absolutely should include your old rules, otherwise, your public registration and public viewing features will stop working. 

Here is the **updated, consolidated ruleset**. It combines your existing "Public Read" and "Public Registration" logic with the new "Support System" and "Staff Security" layers.

### **Updated Firestore Security Rules**
Copy and paste this into the **Rules** tab of your Firebase Console:

```javascript
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    // Helper: Check if the logged-in user is a Support Staff or Super Admin
    function isStaff() {
      return request.auth != null && 
             get(/databases/$(database)/documents/users/$(request.auth.uid)).data.role in ['SUPPORT', 'SUPER_ADMIN'];
    }

    // 1. PUBLIC READ ACCESS (Your original rule)
    // Allows anyone (even not logged in) to see auctions, players, teams, and scores.
    match /{document=**} {
      allow read: if true;
    }

    // 2. PUBLIC PLAYER REGISTRATION (Your original rule)
    // Allows players to sign up without having an account.
    match /auctions/{auctionId}/registrations/{registrationId} {
      allow create: if true;
    }

    // 3. SUPPORT TICKET SYSTEM (New)
    match /supportTickets/{ticketId} {
      // Any logged-in user can create a ticket to ask for help
      allow create: if request.auth != null;

      // Users can read/update their own tickets. Staff can read/update ALL tickets.
      allow read, update: if request.auth != null && (resource.data.userId == request.auth.uid || isStaff());

      // Chat messages inside the ticket
      match /messages/{messageId} {
        allow read, write: if request.auth != null;
      }
    }

    // 4. USER PROFILES (Security Fix)
    // Crucial: Users can only create or edit their OWN profile.
    // This prevents someone from making themselves a 'SUPPORT' user or 'SUPER_ADMIN'.
    match /users/{userId} {
      allow create: if request.auth != null && request.auth.uid == userId;
      allow update: if request.auth != null && (request.auth.uid == userId || isStaff());
    }

    // 5. GENERAL WRITE ACCESS (Your original rule, refined)
    // Allows Admins and Team Owners to manage their specific auction data.
    match /auctions/{auctionId}/{document=**} {
      allow write: if request.auth != null;
    }

    // 6. SYSTEM CONFIGURATION (Staff Only)
    // Only Staff/SuperAdmin can manage plans, promos, and global settings.
    match /subscriptionPlans/{id} { allow write: if isStaff(); }
    match /promoCodes/{id} { allow write: if isStaff(); }
    match /appConfig/{id} { allow write: if isStaff(); }
    match /globalAssets/{id} { allow write: if isStaff(); }
