import React, { useEffect, useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { db, auth } from '../firebase';
import { SupportTicket, SupportMessage, UserRole, UserProfile } from '../types';
import { useAuction } from '../hooks/useAuction';
import { 
    Headset, LogOut, MessageSquare, Clock, CheckCircle, Search, 
    Send, User, AlertCircle, ExternalLink, Activity, Users, 
    ShieldAlert, RefreshCw, ChevronRight, Hash, Mail, Monitor, Filter, X
} from 'lucide-react';

const StaffDashboard = () => {
    const navigate = useNavigate();
    const [tickets, setTickets] = useState<SupportTicket[]>([]);
    const [activeTicketId, setActiveTicketId] = useState<string | null>(null);
    const [activeTicket, setActiveTicket] = useState<SupportTicket | null>(null);
    const [messages, setMessages] = useState<SupportMessage[]>([]);
    const [messageInput, setMessageInput] = useState('');
    const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
    const [showResolved, setShowResolved] = useState(false);
    const [loading, setLoading] = useState(true);
    const [remoteAccessEnabled, setRemoteAccessEnabled] = useState(false);
    const [showFilterOptions, setShowFilterOptions] = useState(false);
    const [sending, setSending] = useState(false);
    const chatEndRef = useRef<HTMLDivElement>(null);
    const [filteredTickets, setFilteredTickets] = useState<SupportTicket[]>([]);

    const { auctionId, connectToRemoteAssistance, disconnectFromRemoteAssistance, isConnecting, isConnected } = useAuction();

    useEffect(() => {
        const unsubscribe = db.collection('supportTickets')
            .orderBy('updatedAt', 'desc')
            .onSnapshot(snapshot => {
                const ticketList: SupportTicket[] = [];
                snapshot.forEach(doc => {
                    const ticketData = doc.data() as SupportTicket;
                    ticketList.push({ ...ticketData, id: doc.id });
                });
                setTickets(ticketList);
                setLoading(false);
            }, error => {
                console.error("Error fetching tickets:", error);
                setLoading(false);
            });

        return () => unsubscribe();
    }, []);

    useEffect(() => {
        const filtered = tickets.filter(ticket =>
            showResolved ? ticket.status === 'RESOLVED' : ticket.status !== 'RESOLVED'
        );
        setFilteredTickets(filtered);
    }, [tickets, showResolved]);

    useEffect(() => {
        if (activeTicketId) {
            const ticket = tickets.find(t => t.id === activeTicketId);
            setActiveTicket(ticket || null);
        } else {
            setActiveTicket(null);
        }
    }, [activeTicketId, tickets]);

    useEffect(() => {
        const fetchUserProfile = async () => {
            if (auth.currentUser) {
                const userDoc = await db.collection('users').doc(auth.currentUser.uid).get();
                if (userDoc.exists) {
                    const userData = userDoc.data() as UserProfile;
                    setUserProfile(userData);
                } else {
                    console.warn('User document not found.');
                }
            }
        };
        fetchUserProfile();
    }, []);

    useEffect(() => {
        if (activeTicketId) {
            const unsubscribe = db.collection('supportTickets')
