import { UserRole } from './types';

const AppContent: React.FC = () => {
  const { userProfile, activeAuctionId } = useAuction();
  const [user, setUser] = useState<firebase.User | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const location = useLocation();

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged((currentUser) => {
      setUser(currentUser);
      setIsLoading(false);
    });
    return () => unsubscribe();
  }, []);

  if (isLoading || (user && !userProfile)) {
    return (
      <div className="min-h-screen bg-primary flex items-center justify-center">
         <div className="flex flex-col items-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-highlight mb-4"></div>
            <p className="text-highlight text-xl animate-pulse">Loading SM SPORTS...</p>
        </div>
      </div>
    );
  }

  const isLoggedIn = !!user;
  const isSuperAdmin = userProfile?.role === UserRole.SUPER_ADMIN;
  const isSupportStaff = userProfile?.role === UserRole.SUPPORT;
  const isAdmin = userProfile?.role === UserRole.ADMIN || isSuperAdmin || isSupportStaff;
  const isTeamOwner = userProfile?.role === UserRole.TEAM_OWNER;

  const getAuthRedirect = () => {
      if (isSuperAdmin) return "/super-admin";
      if (isSupportStaff) return "/staff-dashboard";
      if (isAdmin) return "/admin";
      if (isTeamOwner && activeAuctionId) return `/auction/${activeAuctionId}`;
      return "/";
  };

  // Visibility Logic: Hide Support Widget on Landing Page or OBS Views
  const isLandingPage = location.pathname === '/';
  const isObsView = location.pathname.includes('obs-') || location.pathname.includes('match-overlay');
  const showSupport = isLoggedIn && !isSupportStaff && !isLandingPage && !isObsView;

  return (
    <>
      <Routes>
          <Route path="/" element={<LandingPage />} />
          <Route path="/guide" element={<PlatformGuide />} />
          <Route path="/auction/:auctionId" element={<Dashboard />} />
          <Route path="/auction/:id/register" element={<PlayerRegistration />} />

          <Route path="/auth" element={
              isLoggedIn ? <Navigate to={getAuthRedirect()} replace /> : <AuthScreen />
          } />

          <Route path="/stafflogin" element={
              isLoggedIn ? <Navigate to={getAuthRedirect()} replace /> : <StaffLogin />
          } />

          <Route path="/staff-dashboard" element={
              isSupportStaff ? <StaffDashboard /> : <Navigate to="/stafflogin" replace />
          } />

          <Route path="/super-admin" element={
              isSuperAdmin ? <SuperAdminDashboard /> : <Navigate to="/auth" replace />
          } />

          <Route path="/admin" element={
              isAdmin ? <AdminDashboard /> : <Navigate to="/auth" replace />
          } />

          <Route path="/admin/new" element={
              isAdmin ? <CreateAuction /> : <Navigate to="/auth" replace />
          } />

          <Route path="/admin/auction/:id/manage" element={
              isAdmin ? <AuctionManage /> : <Navigate to="/auth" replace />
          } />

          <Route path="/scoring" element={
              isAdmin ? <ScoringDashboard /> : <Navigate to="/auth" replace />
          } />
          <Route path="/scoring/:matchId" element={
              isAdmin ? <MatchScorer /> : <Navigate to="/auth" replace />
          } />
          <Route path="/match-overlay/:matchId" element={<MatchOverlay />} />

          <Route path="/obs-overlay/:auctionId" element={<OBSOverlay />} />
          <Route path="/obs-green/:auctionId" element={<OBSGreen />} />

          <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>

      {showSupport && <SupportWidget />}
    </>
  );
}

const App: React.FC = () => {
  return (
      <AppContent />
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../firebase';
import { SupportTicket, SupportMessage, UserRole } from '../types';
import { useAuction } from '../hooks/useAuction';
import { Headset, X, Send, RefreshCw, ChevronRight, Zap, CheckCircle, Lock } from 'lucide-react';

const SupportWidget: React.FC = () => {
    const { userProfile, activeAuctionId } = useAuction();
    const [isOpen, setIsOpen] = useState(false);
    const [view, setView] = useState<'BOT' | 'CHAT' | 'TICKET_FORM'>('BOT');
    const [ticket, setTicket] = useState<SupportTicket | null>(null);
    const [messages, setMessages] = useState<SupportMessage[]>([]);
    const [input, setInput] = useState('');
    const [isProcessing, setIsProcessing] = useState(false);
    const scrollRef = useRef<HTMLDivElement>(null);

    const QUICK_REPLIES = [
        { id: 'obs', label: 'OBS Setup Help', response: 'Our professional OBS overlays can be added as a "Browser Source". Would you like a live staff member to guide you?' },
        { id: 'bid', label: 'Bid Corrections', response: 'If a bid was entered incorrectly, use the "Undo Last Action" button on your admin panel. Still need help?' },
        { id: 'budget', label: 'Budget/Purse Issue', response: 'Budgets are auto-calculated. If you manually changed a sale price, it updates immediately. Should I connect you to staff?' },
        { id: 'staff', label: 'Speak to Staff', response: 'Connecting you to our team. Please describe your issue clearly.' }
    ];

    useEffect(() => {
        if (!isOpen || !userProfile?.uid) return;

        // Listen ONLY for tickets belonging to this specific user
        const unsub = db.collection('supportTickets')
            .where('userId', '==', userProfile.uid)
            .orderBy('updatedAt', 'desc')
            .limit(1)
            .onSnapshot(snap => {
                if (!snap.empty) {
                    const t = { id: snap.docs[0].id, ...snap.docs[0].data() } as SupportTicket;
                    // Only switch to CHAT if it's NOT resolved, or if we were already in CHAT
                    if (t.status !== 'RESOLVED' || view === 'CHAT') {
                        setTicket(t);
                        setView('CHAT');
                    }
                } else {
                    setTicket(null);
                    if (view === 'CHAT') setView('BOT');
                }
            });
        return () => unsub();
    }, [isOpen, userProfile?.uid]);

    useEffect(() => {
        if (!ticket?.id || view !== 'CHAT') return;
        // Strict message isolation: Listen only to this ticket's messages
        const unsub = db.collection('supportTickets').doc(ticket.id).collection('messages')
            .orderBy('timestamp', 'asc')
            .onSnapshot(snap => {
                setMessages(snap.docs.map(d => ({ id: d.id, ...d.data() } as SupportMessage)));
                setTimeout(() => scrollRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
            });
        return () => unsub();
    }, [ticket?.id, view]);

    const createTicket = async (subject: string, initialMessage?: string) => {
        if (!userProfile) return;
        setIsProcessing(true);
        try {
            const ticketId = `TIC-${Math.random().toString(36).substr(2, 6).toUpperCase()}`;
            const newTicket: SupportTicket = {
                id: ticketId,
                userId: userProfile.uid,
                userName: userProfile.name || 'Anonymous',
                userEmail: userProfile.email,
                auctionId: activeAuctionId || '',
                subject,
                status: 'OPEN',
                priority: 'MEDIUM',
                createdAt: Date.now(),
                updatedAt: Date.now()
            };
            await db.collection('supportTickets').doc(ticketId).set(newTicket);

            if (initialMessage) {
                await db.collection('supportTickets').doc(ticketId).collection('messages').add({
                    ticketId,
                    senderId: userProfile.uid,
                    senderName: userProfile.name || 'User',
                    senderRole: userProfile.role,
                    text: initialMessage,
                    timestamp: Date.now()
                });
            }
            setView('CHAT');
        } catch (e) { alert("Protocol offline. Try again later."); }
        finally { setIsProcessing(false); }
    };

    const sendMessage = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!input.trim() || !ticket || !userProfile || isProcessing || ticket.status === 'RESOLVED') return;
        setIsProcessing(true);
        try {
            await db.collection('supportTickets').doc(ticket.id).collection('messages').add({
                ticketId: ticket.id,
                senderId: userProfile.uid,
                senderName: userProfile.name || 'User',
                senderRole: userProfile.role,
                text: input,
                timestamp: Date.now()
            });
            await db.collection('supportTickets').doc(ticket.id).update({ updatedAt: Date.now() });
            setInput('');
        } catch (e) { console.error(e); }
        finally { setIsProcessing(false); }
    };

    const handleCloseWidget = () => {
        setIsOpen(false);
        // If the ticket was resolved, reset the view so next time they open it's clean
        if (ticket?.status === 'RESOLVED') {
            setView('BOT');
            setTicket(null);
        }
    };

    return (
        <div className="fixed bottom-6 right-6 z-[100] font-sans">
            {!isOpen ? (
                <button 
                    onClick={() => setIsOpen(true)}
                    className="bg-blue-600 hover:bg-blue-500 text-white w-14 h-14 rounded-full shadow-2xl flex items-center justify-center transition-all hover:scale-110 active:rotate-12 border-4 border-white/20 relative group"
                >
                    <Headset className="w-6 h-6" />
                    <span className="absolute -top-1 -right-1 w-4 h-4 bg-emerald-500 border-2 border-slate-950 rounded-full"></span>
                </button>
            ) : (
                <div className="bg-slate-900 w-80 h-[500px] rounded-[2.5rem] shadow-[0_30px_100px_rgba(0,0,0,0.6)] border border-white/10 overflow-hidden flex flex-col animate-slide-up">
                    <div className="bg-blue-600 p-6 flex justify-between items-center relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-24 h-24 bg-white/5 rounded-full -translate-y-1/2 translate-x-1/2"></div>
                        <div className="flex items-center gap-3 relative z-10">
                            <div className="w-10 h-10 bg-white/10 backdrop-blur rounded-xl flex items-center justify-center border border-white/20">
                                <Headset className="w-5 h-5 text-white" />
                            </div>
                            <div>
                                <h3 className="text-white font-black uppercase text-xs tracking-widest">Help Desk</h3>
                                <p className="text-blue-100 text-[8px] font-black uppercase tracking-[0.3em] opacity-60">Status: {ticket?.status === 'RESOLVED' ? 'Archived' : 'Secure'}</p>
                            </div>
                        </div>
                        <button onClick={handleCloseWidget} className="text-white/60 hover:text-white transition-colors relative z-10"><X className="w-5 h-5"/></button>
                    </div>

                    <div className="flex-1 overflow-y-auto p-4 custom-scrollbar bg-black/20">
                        {view === 'BOT' && (
                            <div className="space-y-4 animate-fade-in">
                                <div className="bg-slate-800 p-4 rounded-2xl rounded-bl-none text-xs font-medium text-slate-300 leading-relaxed shadow-lg">
                                    Welcome. I can help with standard issues or connect you to our support staff.
                                </div>
                                <div className="grid grid-cols-1 gap-2">
                                    {QUICK_REPLIES.map(q => (
                                        <button 
                                            key={q.id}
                                            onClick={() => q.id === 'staff' ? setView('TICKET_FORM') : createTicket(q.label, q.response)}
                                            className="w-full text-left p-3 rounded-xl border border-white/5 bg-slate-900/50 hover:bg-blue-600/10 hover:border-blue-500/30 text-[10px] font-black text-slate-400 hover:text-blue-400 uppercase tracking-widest transition-all flex justify-between items-center"
                                        >
                                            {q.label} <ChevronRight className="w-3 h-3" />
                                        </button>
                                    ))}
                                </div>
                            </div>
                        )}

                        {view === 'TICKET_FORM' && (
                            <div className="space-y-4 animate-fade-in">
                                <button onClick={() => setView('BOT')} className="text-[8px] font-black text-slate-500 hover:text-white flex items-center gap-1 uppercase mb-4">
                                    <ChevronRight className="w-3 h-3 rotate-180" /> Go Back
                                </button>
                                <h4 className="text-[10px] font-black text-blue-400 uppercase tracking-[0.2em] mb-4">Support Request</h4>
                                <div className="space-y-3">
                                    <input className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 text-xs font-bold text-white outline-none" placeholder="SUBJECT" id="sub" />
                                    <textarea className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 text-xs font-bold text-white min-h-[100px] outline-none" placeholder="DETAILS" id="desc" />
                                    <button 
                                        onClick={() => {
                                            const s = (document.getElementById('sub') as HTMLInputElement).value;
                                            const d = (document.getElementById('desc') as HTMLTextAreaElement).value;
                                            if (s && d) createTicket(s, d);
                                        }}
                                        disabled={isProcessing}
                                        className="w-full bg-blue-600 text-white font-black py-3 rounded-xl shadow-lg uppercase text-[10px] tracking-widest transition-all"
                                    >
                                        {isProcessing ? <RefreshCw className="w-4 h-4 animate-spin mx-auto"/> : 'INITIALIZE'}
                                    </button>
                                </div>
                            </div>
                        )}

                        {view === 'CHAT' && ticket && (
                            <div className="space-y-4 pb-4 animate-fade-in">
                                <div className="text-center pb-4 border-b border-white/5">
                                    <p className="text-[9px] font-black text-blue-400 uppercase tracking-[0.3em]">Protocol #{ticket.id.split('-').pop()}</p>
                                    <p className={`text-[8px] font-bold uppercase mt-1 ${ticket.status === 'RESOLVED' ? 'text-slate-500' : 'text-emerald-400'}`}>
                                        Status: {ticket.status === 'OPEN' ? 'Queueing...' : ticket.status === 'IN_PROGRESS' ? 'Staff Connected' : 'Session Archived'}
                                    </p>
                                </div>
                                {messages.map(m => (
                                    <div key={m.id} className={`flex ${m.senderRole === UserRole.SUPPORT ? 'justify-start' : 'justify-end'}`}>
                                        <div className={`max-w-[85%] p-3 rounded-2xl text-[11px] font-medium leading-relaxed shadow-lg ${m.senderRole === UserRole.SUPPORT ? 'bg-slate-800 text-slate-200 rounded-bl-none' : 'bg-blue-600 text-white rounded-br-none'}`}>
                                            {m.text}
                                        </div>
                                    </div>
                                ))}
                                {ticket.status === 'RESOLVED' && (
                                    <div className="bg-slate-950/50 p-4 rounded-2xl border border-white/5 text-center mt-4">
                                        <CheckCircle className="w-6 h-6 text-emerald-500 mx-auto mb-2" />
                                        <p className="text-[10px] font-black text-white uppercase mb-1">Issue Resolved</p>
                                        <p className="text-[8px] text-slate-500 font-bold uppercase">This support session has ended.</p>
                                        <button onClick={() => { setView('BOT'); setTicket(null); }} className="mt-3 text-[8px] font-black text-blue-500 uppercase tracking-widest underline">Start New Session</button>
                                    </div>
                                )}
                                <div ref={scrollRef} />
                            </div>
                        )}
                    </div>

                    {view === 'CHAT' && ticket && ticket.status !== 'RESOLVED' && (
                        <div className="p-4 bg-slate-900 border-t border-white/5">
                            <form onSubmit={sendMessage} className="relative">
                                <input 
                                    value={input} 
                                    onChange={e => setInput(e.target.value)}
                                    placeholder="MESSAGE..." 
                                    className="w-full bg-slate-950 border border-slate-800 rounded-full py-3 pl-4 pr-12 text-xs font-bold text-white outline-none focus:border-blue-500" 
                                />
                                <button type="submit" disabled={isProcessing || !input.trim()} className="absolute right-2 top-1/2 -translate-y-1/2 bg-blue-600 text-white p-2 rounded-full transition-all disabled:opacity-50">
                                    {isProcessing ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
                                </button>
                            </form>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default SupportWidget;

import React, { useEffect, useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { db, auth } from '../firebase';
import { SupportTicket, SupportMessage, UserRole } from '../types';
import { useAuction } from '../hooks/useAuction';
import { 
    Headset, LogOut, MessageSquare, Clock, CheckCircle, Search, 
    Send, RefreshCw, ChevronRight, Mail, Monitor, X
} from 'lucide-react';

const StaffDashboard: React.FC = () => {
    const navigate = useNavigate();
    const { userProfile, joinAuction } = useAuction();
    const [tickets, setTickets] = useState<SupportTicket[]>([]);
    const [activeTicketId, setActiveTicketId] = useState<string | null>(null);
    const [messages, setMessages] = useState<SupportMessage[]>([]);
    const [reply, setReply] = useState('');
    const [loading, setLoading] = useState(true);
    const [isSending, setIsSending] = useState(false);
    const [showResolved, setShowResolved] = useState(false);
    const scrollRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const unsub = db.collection('supportTickets')
            .orderBy('updatedAt', 'desc')
            .onSnapshot(snap => {
                setTickets(snap.docs.map(d => ({ id: d.id, ...d.data() } as SupportTicket)));
                setLoading(false);
            });
        return () => unsub();
    }, []);

    useEffect(() => {
        if (!activeTicketId) {
            setMessages([]);
            return;
        }
        const unsub = db.collection('supportTickets').doc(activeTicketId).collection('messages')
            .orderBy('timestamp', 'asc')
            .onSnapshot(snap => {
                setMessages(snap.docs.map(d => ({ id: d.id, ...d.data() } as SupportMessage)));
                setTimeout(() => scrollRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
            });
        return () => unsub();
    }, [activeTicketId]);

    const handleSelectTicket = async (ticket: SupportTicket) => {
        setActiveTicketId(ticket.id);
        if (ticket.status === 'OPEN' && userProfile) {
            try {
                await db.collection('supportTickets').doc(ticket.id).update({
                    status: 'IN_PROGRESS',
                    staffId: userProfile.uid,
                    staffName: userProfile.name || 'Staff',
                    updatedAt: Date.now()
                });
            } catch (err) { console.error(err); }
        }
    };

    const handleSendMessage = async (e: React.FormEvent) => {
        e.preventDefault();
        const cleanReply = reply.trim();
        if (!cleanReply || !activeTicketId || !userProfile || isSending) return;

        const currentTicket = tickets.find(t => t.id === activeTicketId);
        if (!currentTicket || currentTicket.status === 'RESOLVED') return;

        setIsSending(true);
        try {
            await db.collection('supportTickets').doc(activeTicketId).collection('messages').add({
                ticketId: activeTicketId,
                senderId: userProfile.uid,
                senderName: userProfile.name || 'Staff',
                senderRole: UserRole.SUPPORT,
                text: cleanReply,
                timestamp: Date.now()
            });

            await db.collection('supportTickets').doc(activeTicketId).update({ 
                updatedAt: Date.now(),
                status: 'IN_PROGRESS' 
            });
            setReply('');
        } catch (err) { alert("Failed to send message."); }
        finally { setIsSending(false); }
    };

    const handleResolve = async (ticketId: string) => {
        if (!ticketId) return;
        if (window.confirm("Archive this conversation and mark as Resolved?")) {
            try {
                await db.collection('supportTickets').doc(ticketId).update({ 
                    status: 'RESOLVED', 
                    updatedAt: Date.now() 
                });
                if (activeTicketId === ticketId) setActiveTicketId(null);
                setShowResolved(true);
            } catch (err) { alert("Failed to resolve ticket."); }
        }
    };

    const handleEnterInstance = (auctionId: string) => {
        if (!auctionId) return alert("No instance ID linked.");
        if (window.confirm("Entering Remote Admin Mode. Proceed?")) {
            joinAuction(auctionId);
            navigate(`/auction/${auctionId}`);
        }
    };

    const filteredTickets = tickets.filter(t => showResolved ? t.status === 'RESOLVED' : t.status !== 'RESOLVED');
    const activeTicket = tickets.find(t => t.id === activeTicketId);

    return (
        <div className="min-h-screen bg-slate-950 text-white flex flex-col font-sans">
            <nav className="bg-slate-900 border-b border-white/5 px-6 py-4 flex justify-between items-center sticky top-0 z-50">
                <div className="flex items-center gap-4">
                    <div className="bg-blue-600 p-2.5 rounded-xl shadow-lg"><Headset className="w-6 h-6 text-white" /></div>
                    <div>
                        <h1 className="text-xl font-black uppercase tracking-tighter text-blue-50">Support Dashboard</h1>
                        <p className="text-[9px] text-slate-500 font-black uppercase tracking-[0.3em] mt-1 opacity-60">System Protocol Engine</p>
                    </div>
                </div>
                <button onClick={() => auth.signOut()} className="bg-slate-800 hover:bg-red-600 px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all border border-white/5">Logout</button>
            </nav>

            <main className="flex-1 flex overflow-hidden">
                <div className="w-96 border-r border-white/5 flex flex-col bg-slate-900/30">
                    <div className="p-6 border-b border-white/5 space-y-4">
                        <div className="flex items-center justify-between bg-black/20 p-1 rounded-xl border border-white/5">
                            <button onClick={() => setShowResolved(false)} className={`flex-1 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${!showResolved ? 'bg-blue-600 text-white' : 'text-slate-500'}`}>Active</button>
                            <button onClick={() => setShowResolved(true)} className={`flex-1 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${showResolved ? 'bg-slate-700 text-white' : 'text-slate-500'}`}>Archived</button>
                        </div>
                    </div>
                    <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-4">
                        {filteredTickets.map(t => (
                            <div key={t.id} onClick={() => handleSelectTicket(t)} className={`p-5 rounded-[1.5rem] border-2 cursor-pointer transition-all ${activeTicketId === t.id ? 'bg-blue-600/10 border-blue-600 shadow-xl' : 'bg-slate-900/50 border-white/5 hover:border-white/10'}`}>
                                <div className="flex justify-between items-start mb-2">
                                    <span className="text-[10px] font-black text-blue-400">#{t.id.split('-').pop()}</span>
                                    <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase ${t.status === 'OPEN' ? 'bg-emerald-500 text-white animate-pulse' : t.status === 'IN_PROGRESS' ? 'bg-blue-500 text-white' : 'bg-slate-800 text-slate-500'}`}>{t.status}</span>
                                </div>
                                <h3 className="font-black text-sm uppercase leading-tight truncate">{t.subject}</h3>
                                <p className="text-[10px] text-slate-500 font-bold uppercase truncate mt-1">{t.userName}</p>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="flex-1 flex flex-col relative bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]">
                    {activeTicket ? (
                        <>
                            <div className="p-6 bg-slate-900/90 backdrop-blur-md border-b border-white/5 flex justify-between items-center z-10">
                                <div className="flex items-center gap-4">
                                    <div className="w-12 h-12 rounded-full bg-blue-600 flex items-center justify-center font-black text-white">{activeTicket.userName.charAt(0)}</div>
                                    <div>
                                        <h2 className="font-black uppercase text-lg leading-none mb-1">{activeTicket.userName}</h2>
                                        <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest">{activeTicket.userEmail}</p>
                                    </div>
                                </div>
