                            <div className={`p-6 bg-slate-900 border-t border-white/5 ${activeTicket.status === 'RESOLVED' ? 'opacity-40 grayscale pointer-events-none' : ''}`}>
                                <form onSubmit={handleSendMessage} className="relative">
