                                    <h2 className="text-3xl font-black uppercase tracking-tighter">Retention Policy</h2>
                                    <p className="text-zinc-500 text-xs font-bold uppercase tracking-widest mt-1">Configure global automated purging</p>
                                </div>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                                <div>
                                    <label className="block text-[10px] font-black text-zinc-400 uppercase tracking-widest mb-4">Default Retention Period (Days)</label>
                                    <div className="flex items-center gap-4">
                                        <input type="number" value={retentionDays} onChange={e => setRetentionDays(Number(e.target.value))} className="w-24 bg-black border border-white/10 rounded-2xl py-4 text-center text-xl font-black" />
