                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {activeTab === 'GRAPHICS' && (
                    <div className="space-y-6 animate-fade-in">
                        <div className="flex justify-between items-center">
                            <h2 className="text-2xl font-black uppercase tracking-tighter">Global Asset Library</h2>
                            <div className="flex gap-2">
                                <input type="file" id="asset-up" className="hidden" accept="image/*" onChange={async (e) => {
                                    if(e.target.files?.[0]) setAssetPreview(await compressImage(e.target.files[0]));
                                }} />
                                <button onClick={() => document.getElementById('asset-up')?.click()} className="bg-zinc-800 px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest border border-white/5 hover:bg-zinc-700">SELECT IMAGE</button>
                                <button onClick={async () => {
                                    if(assetPreview) { await db.collection('globalAssets').add({ url: assetPreview, name: 'Global Asset ' + Date.now(), createdAt: Date.now(), type: 'BACKGROUND' }); setAssetPreview(''); alert("Deployed."); }
                                }} className="bg-blue-600 px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">DEPLOY TO ALL</button>
                            </div>
                        </div>
                        {assetPreview && <div className="w-full h-48 bg-zinc-900 rounded-3xl overflow-hidden mb-6 flex justify-center p-4 border border-blue-500/30"><img src={assetPreview} className="max-h-full object-contain" /></div>}
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                            {globalAssets.map(asset => (
                                <div key={asset.id} className="aspect-video bg-zinc-900 rounded-2xl border border-white/5 overflow-hidden group relative">
                                    <img src={asset.url} className="w-full h-full object-cover group-hover:scale-110 transition-all duration-500" />
                                    <button onClick={async () => db.collection('globalAssets').doc(asset.id).delete()} className="absolute top-2 right-2 bg-red-600 p-2 rounded-full opacity-0 group-hover:opacity-100 transition-all"><Trash2 className="w-3 h-3 text-white"/></button>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </main>

            {/* Modals Implementation to ensure full restoration */}
            {isAddingPlan && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
                    <div className="bg-zinc-900 p-8 rounded-[2.5rem] border border-white/10 w-full max-w-md shadow-2xl">
                        <div className="flex justify-between items-center mb-6">
                            <h3 className="text-xl font-black uppercase tracking-tighter">Monetization Tier</h3>
                            <button onClick={() => setIsAddingPlan(false)}><XCircle className="w-6 h-6 text-zinc-500"/></button>
                        </div>
                        <form onSubmit={handleSavePlan} className="space-y-4">
                            <input placeholder="PLAN NAME" className="w-full bg-black border border-white/10 rounded-2xl py-4 px-6 text-xs font-bold" value={planForm.name} onChange={e => setPlanForm({...planForm, name: e.target.value})} required />
                            <input type="number" placeholder="PRICE (₹)" className="w-full bg-black border border-white/10 rounded-2xl py-4 px-6 text-xs font-bold" value={planForm.price} onChange={e => setPlanForm({...planForm, price: Number(e.target.value)})} required />
                            <input type="number" placeholder="MAX TEAMS" className="w-full bg-black border border-white/10 rounded-2xl py-4 px-6 text-xs font-bold" value={planForm.teams} onChange={e => setPlanForm({...planForm, teams: Number(e.target.value)})} required />
                            <button type="submit" className="w-full bg-blue-600 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl">AUTHORIZE PLAN</button>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SuperAdminDashboard;

export enum PlayerCategory {
  Batsman = "Batsman",
  Bowler = "Bowler",
  AllRounder = "All-Rounder",
  Wicketkeeper = "Wicketkeeper",
}

export interface PlayerRole {
    id?: string;
    name: string;
    basePrice: number; // Default base price for this role
}

export interface Player {
  id: number | string;
  name: string;
  photoUrl: string;
  category: string; // Auction Category (Group: MVP, Set 1, Uncapped)
  role: string;     // Player Type (Skill: Batsman, Bowler)
  basePrice: number;
  nationality: string;
  speciality: string; // Kept for backward compat, usually same for role
  stats: {
    matches: number;
    runs: number;
    wickets: number;
  };
  status?: 'SOLD' | 'UNSOLD';
  soldPrice?: number;
  soldTo?: string;
}

export interface PromoCode {
    id?: string;
    code: string;
    discountType: 'PERCENT' | 'FLAT';
    discountValue: number;
    maxClaims: number;
    currentClaims: number;
    expiryDate: number;
    active: boolean;
}

export interface RegisteredPlayer {
    id: string;
    fullName: string;
    mobile: string;
    playerType: string;
    gender: string;
    dob: string;
    profilePic: string;
    paymentScreenshot?: string;
    razorpayPaymentId?: string;
    status: 'PENDING' | 'APPROVED' | 'REJECTED';
    submittedAt: number;
    [key: string]: any; // For custom fields
}

export interface Team {
  id: number | string;
  name: string;
  shortName?: string;
  owner: string;
  logoUrl: string;
  budget: number;
  players: Player[];
  minPlayers?: number;
  maxPlayers?: number;
  password?: string; // Added password for team login
}

export interface Bid {
  teamId: number | string;
  amount: number;
}

export enum AuctionStatus {
  NotStarted = "NOT_STARTED",
  InProgress = "IN_PROGRESS",
  Paused = "PAUSED",
  Sold = "SOLD",
  Unsold = "UNSOLD",
  Finished = "FINISHED",
}

export interface AuctionLog {
  message: string;
  timestamp: number;
  type: 'SYSTEM' | 'BID' | 'SOLD' | 'UNSOLD';
}

export interface BidIncrementSlab {
    from: number;
    increment: number;
}

export interface AuctionCategory {
    id?: string;
    name: string;
    basePrice: number;
    minPerTeam: number;
    maxPerTeam: number;
    bidIncrement: number;
    bidLimit: number;
    slabs: BidIncrementSlab[];
}

export interface Sponsor {
    id: string;
    name: string;
    imageUrl: string;
}

export interface SponsorConfig {
    showOnOBS: boolean;
    showOnProjector: boolean;
    showHighlights?: boolean; // New: Toggle for news ticker highlights
    loopInterval: number; // seconds
}

export type ProjectorLayout = 'STANDARD' | 'IPL' | 'MODERN';
export type OBSLayout = 'STANDARD' | 'MINIMAL' | 'VERTICAL';

export type AdminViewType = 'SQUAD' | 'PURSES' | 'UNSOLD' | 'SOLD' | 'TOP_BUY' | 'TOP_5' | 'NONE';

export interface AdminViewOverride {
    type: AdminViewType;
    data?: any; // e.g. { teamId: '...' }
}

export type BiddingStatus = 'ON' | 'PAUSED' | 'HIDDEN';

export interface AuctionState {
  players: Player[];
  teams: Team[];
  unsoldPlayers: Player[]; // This is the pool of available players
  categories: AuctionCategory[]; // Available categories with rules
  roles: PlayerRole[]; // Added Roles to State
  status: AuctionStatus;
  currentPlayerId: string | number | null; // Source of truth for current player
  currentPlayerIndex: number | null; // Derived helper
  currentBid: number | null;
  highestBidder: Team | null;
  timer: number;
  bidIncrement: number; // Global fallback increment
  bidSlabs?: BidIncrementSlab[]; // Global fallback slabs
  auctionLog: AuctionLog[];
  biddingStatus: BiddingStatus; // Replaces biddingEnabled
  playerSelectionMode: 'MANUAL' | 'AUTO';
  auctionLogoUrl?: string;
  tournamentName?: string;
  sponsors: Sponsor[];
  sponsorConfig: SponsorConfig;
  projectorLayout: ProjectorLayout;
  obsLayout: OBSLayout;
  adminViewOverride: AdminViewOverride | null;
  maxPlayersPerTeam?: number; // Global Squad Limit
  systemLogoUrl?: string; // Global System Branding Logo
  isPaid?: boolean; // Per-auction payment status
  planId?: string; // Plan ID associated with auction
  autoDeleteAt?: number; // Scheduled deletion timestamp
  isLifetime?: boolean; // No auto-delete flag
}

