                    </button>

                    <p className="text-[9px] text-gray-400 font-bold text-center uppercase tracking-widest leading-relaxed">
                        By submitting, you agree to the tournament protocols <br/> and verify all information is legally accurate.
                    </p>
                </form>
            </div>
        </div>
    );
};

